#define PI 3.1415926538

float rnd(vec2 p, float n) {
    return fract(abs(sin(p.x*123.4+p.y*432.1)*(p.x*3.7+p.x*p.y*4.5+256.7+n*654.3)+n*321.1));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    float t = mod(iTime,6.0);
    float n = floor(iTime/6.0);
    vec3 col;
    float l = pow(length(uv),2.0);
    float a = atan(uv.y, uv.x)/PI;
    if(mod(n,2.0)==0.0) {
        float t0 = t;
        t = pow(t,2.6);
        uv = vec2(l, a);

        float v=1.0;
        for(float y=-1.0;y<1.0;y+=0.2) {
            for(float x=-1.0;x<1.0;x+=0.2) {
                vec2 p = vec2(x,y);
                vec2 d = vec2(rnd(p, n+1.0)*0.1-0.05, rnd(p, n+2.0)*0.2-0.1);
                v=min(v, distance(uv,p+d));
                v=min(v, distance(uv-vec2(0.0,2.0),p+d));
            }
        }
        v*=l>0.9?1.0-(l-0.9)*10.0:1.0;
        v=clamp(v*(4.0+t/48.0+sin(t)),0.0,1.0);
        v=min(pow(v,2.0),1.0);
        if(t<1.0)v*=t;
        if(t0>5.0) {
            v+=(1.0-l)*(t0-5.0);
            v+=abs(l-(t0-5.0))/2.0;
        }
        col=vec3(clamp(v*3.0,0.0,1.0),clamp(v*3.0-1.0,0.0,1.0), clamp(v*3.0-2.0,0.0,1.0));

    } else {
        float v = l<0.9?(1.0-pow(t/6.0,3.0)):(1.0-(l<1.0?l:1.0))*10.0;
        v = min(v, 1.0);
        if(l>0.9) {
            float mx = 0.05*(6.0-t)/6.0;
            for(float i=0.0;i<10.0;++i) {
                float aa = i/10.0+rnd(vec2(i,i), n)/10.0;
                aa += sin(iTime/4.0+10.0*rnd(vec2(i,i),n+1.0))/20.0;
                aa = fract(aa+1.0);
                aa = aa*2.0-1.0;
                float d = min(abs(aa-a),min(abs(aa-a-2.0),abs(aa-a+2.0)));
                v+=d<mx?pow((mx-d)*25.0,0.4):0.0;
            }
        }
        if(t>5.0) {
            v*=(6.0-t);
        }
        v=min(v,1.0);

        col=vec3(clamp(v*3.0,0.0,1.0),clamp(v*3.0-1.0,0.0,1.0), clamp(v*3.0-2.0,0.0,1.0));

    }
    // Output to screen
    fragColor = vec4(col,1.0);
}
